def caesar(text, shift):
    out = ""
    for ch in text:
        if "A" <= ch <= "Z":
            out += chr((ord(ch) - 65 + shift) % 26 + 65)
        else:
            out += ch
    return out

def vigenere(text, key):
    out, k = "", 0
    for c in text:
        if "A" <= c <= "Z":
            shift = ord(key[k % len(key)]) - ord("A")
            out += chr((ord(c) - ord("A") + shift) % 26 + ord("A"))
            k += 1
        else:
            out += c
    return out

