net-ip.solution:
import ipaddress


def route(table, ip):
    address = ipaddress.ip_address(ip)
    best, best_len = None, -1
    for cidr, hop in table:
        net = ipaddress.ip_network(cidr)
        if address in net and net.prefixlen > best_len:
            best, best_len = hop, net.prefixlen
    return best

