class MinSegmentTree:
    def __init__(self, nums):
        self.n = len(nums)
        self.tree = [0] * (4 * self.n)
        self._build(nums, 0, 0, self.n - 1)

    def _build(self, nums, node, lo, hi):
        if lo == hi:
            self.tree[node] = nums[lo]
            return
        mid = (lo + hi) // 2
        self._build(nums, 2 * node + 1, lo, mid)
        self._build(nums, 2 * node + 2, mid + 1, hi)
        self.tree[node] = min(self.tree[2 * node + 1], self.tree[2 * node + 2])

    def update(self, i, value, node=0, lo=0, hi=None):
        if hi is None:
            hi = self.n - 1
        if lo == hi:
            self.tree[node] = value
            return
        mid = (lo + hi) // 2
        if i <= mid:
            self.update(i, value, 2 * node + 1, lo, mid)
        else:
            self.update(i, value, 2 * node + 2, mid + 1, hi)
        self.tree[node] = min(self.tree[2 * node + 1], self.tree[2 * node + 2])

    def min_query(self, l, r, node=0, lo=0, hi=None):
        if hi is None:
            hi = self.n - 1
        if r < lo or hi < l:
            return float('inf')
        if l <= lo and hi <= r:
            return self.tree[node]
        mid = (lo + hi) // 2
        return min(self.min_query(l, r, 2 * node + 1, lo, mid),
                   self.min_query(l, r, 2 * node + 2, mid + 1, hi))


def run(nums, ops):
    st = MinSegmentTree(nums)
    out = []
    for op, a, b in ops:
        if op == 'set':
            st.update(a, b)
        else:
            out.append(st.min_query(a, b))
    return out

