string-algorithms.solution:
def count_occurrences(text, pattern):
    BASE, MOD = 256, 1_000_000_007
    m, n = len(pattern), len(text)
    if m > n:
        return 0
    high = pow(BASE, m - 1, MOD)
    p_hash = w_hash = 0
    for i in range(m):
        p_hash = (p_hash * BASE + ord(pattern[i])) % MOD
        w_hash = (w_hash * BASE + ord(text[i])) % MOD
    count = 0
    for start in range(n - m + 1):
        if w_hash == p_hash and text[start:start + m] == pattern:
            count += 1
        if start + m < n:
            w_hash = (w_hash - ord(text[start]) * high) % MOD
            w_hash = (w_hash * BASE + ord(text[start + m])) % MOD
    return count

