class Solution {
    static String fizzBuzz(int n) {
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            if (i > 1) sb.append(' ');            // a space between items, not before the first
            if (i % 15 == 0) sb.append("FizzBuzz"); // check "both" first
            else if (i % 3 == 0) sb.append("Fizz");
            else if (i % 5 == 0) sb.append("Buzz");
            else sb.append(i);
        }
        return sb.toString();
    }
}

