class Solution {
    static int digitalRoot(int n) {
        while (n >= 10) {          // more than one digit left
            int sum = 0;
            while (n > 0) {
                sum += n % 10;     // last digit
                n /= 10;           // drop the last digit
            }
            n = sum;
        }
        return n;
    }
}

