class Solution {
    static class Rectangle {
        private final int width, height;   // final: a Rectangle never changes after it is built

        Rectangle(int width, int height) {
            this.width = width;
            this.height = height;
        }

        int area() {
            return width * height;
        }

        int perimeter() {
            return 2 * (width + height);
        }

        boolean isSquare() {
            return width == height;
        }

        Rectangle scale(int factor) {
            return new Rectangle(width * factor, height * factor);
        }

        @Override
        public String toString() {
            return width + "x" + height;
        }
    }
}

