class Solution {
    static class InvalidAgeException extends Exception {
        InvalidAgeException(String message) {
            super(message);
        }
    }

    static int checkAge(int age) throws InvalidAgeException {
        if (age < 0) throw new InvalidAgeException("age cannot be negative");
        if (age > 150) throw new InvalidAgeException("age is too large");
        return age;
    }

    static String describe(int age) {
        try {
            return "ok: " + checkAge(age);
        } catch (InvalidAgeException e) {
            return "invalid: " + e.getMessage();   // the message passed to the constructor
        }
    }
}

