import java.util.*;

class Solution {
    static <T extends Comparable<T>> T maxOf(List<T> items) {
        T best = null;
        for (T item : items) {
            // compareTo is available because T extends Comparable<T>
            if (best == null || item.compareTo(best) > 0) best = item;
        }
        return best;
    }
}

