import java.util.*;

class Solution {
    static Map<String, Integer> wordCounts(String text) {
        Map<String, Integer> counts = new TreeMap<>();   // keeps keys sorted
        for (String word : text.toLowerCase().split(" ")) {
            if (word.isEmpty()) continue;                  // extra spaces give empty pieces
            counts.merge(word, 1, Integer::sum);           // 1 if new, otherwise add 1
        }
        return counts;
    }
}

