import java.io.*;

class Solution {
    static int countLines(String text) throws IOException {
        int count = 0;
        // try-with-resources closes the reader, exactly as it would close a file
        try (BufferedReader reader = new BufferedReader(new StringReader(text))) {
            String line;
            while ((line = reader.readLine()) != null) {   // null means end of input
                if (!line.isBlank()) count++;
            }
        }
        return count;
    }
}

