multithreading.solution:
import java.util.*;
import java.util.concurrent.*;

class Solution {
    static long parallelSum(int[] nums, int parts) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(parts);
        try {
            List<Future<Long>> futures = new ArrayList<>();
            int size = (nums.length + parts - 1) / parts;   // chunk size, rounded up
            for (int start = 0; start < nums.length; start += size) {
                int from = start, to = Math.min(start + size, nums.length);
                futures.add(pool.submit(() -> {              // runs on a pool thread
                    long sum = 0;
                    for (int i = from; i < to; i++) sum += nums[i];
                    return sum;
                }));
            }
            long total = 0;
            for (Future<Long> f : futures) total += f.get();  // get() waits for that chunk
            return total;
        } finally {
            pool.shutdown();                                  // always release the threads
        }
    }
}

