multithreading.solution:
import java.util.*;
import java.util.concurrent.atomic.*;

class Solution {
    static int countWithThreads(int threads, int incrementsEach) throws InterruptedException {
        AtomicInteger counter = new AtomicInteger();
        List<Thread> started = new ArrayList<>();
        for (int t = 0; t < threads; t++) {
            Thread thread = new Thread(() -> {
                for (int i = 0; i < incrementsEach; i++) counter.incrementAndGet();   // atomic, unlike count++
            });
            thread.start();
            started.add(thread);
        }
        for (Thread thread : started) thread.join();   // wait until every thread has finished
        return counter.get();
    }
}

