import java.util.Objects;

class Solution {
    static class Point {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;                      // same object
            if (!(o instanceof Point)) return false;         // also handles null
            Point p = (Point) o;
            return x == p.x && y == p.y;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y);   // equal points must give equal hash codes
        }
    }
}

