design-patterns.solution:
import java.util.*;

class Solution {
    static class Pizza {
        private final String size;
        private final List<String> toppings;

        private Pizza(Builder b) {                 // only the Builder can make a Pizza
            this.size = b.size;
            this.toppings = List.copyOf(b.toppings);   // a fixed copy the builder cannot change later
        }

        @Override
        public String toString() {
            String list = toppings.isEmpty() ? "no toppings" : String.join(", ", toppings);
            return size + " pizza with " + list;
        }

        static class Builder {
            private String size = "medium";        // sensible defaults
            private final List<String> toppings = new ArrayList<>();

            Builder size(String size) {
                this.size = size;
                return this;                       // returning this allows chaining
            }

            Builder addTopping(String topping) {
                toppings.add(topping);
                return this;
            }

            Pizza build() {
                return new Pizza(this);
            }
        }
    }
}

