design-patterns.solution:
class Solution {
    interface Discount {
        double apply(double price);
    }

    static Discount forCode(String code) {
        // each case returns a different strategy; the caller just calls apply()
        switch (code) {
            case "HALF":
                return price -> price * 0.5;
            case "TENOFF":
                return price -> Math.max(0, price - 10);
            default:
                return price -> price;   // no discount
        }
    }
}

